import React from 'react';

const Contact = () => (
  <section id="contact">
    <div className="container">
      <h2>Contact Me</h2>
      <p className="contact-item">
        Email: <a href="mailto:muhammadshahan92@gmail.com">muhammadshahan92@gmail.com</a>
      </p>
      <p className="contact-item">Phone: +92 333-8033929</p>
      <p className="contact-item">
        LinkedIn: <a href="https://www.linkedin.com/in/muhammad-shahan-152331120/">linkedin.com/in/muhammad-shahan-152331120</a>
      </p>
    </div>
  </section>
);

export default Contact;
